import unittest

from sqlglot import parse_one, ParseError

class TestReprobotSQLGlot8225(unittest.TestCase):
    def test_create_table_auto_increment(self):
        sql = """CREATE TABLE t1(id INT KEY AUTO_INCREMENT);"""
        with self.assertRaises(ParseError):
            parse_one(sql, read='mysql')

if __name__ == '__main__':
    unittest.main()
